/**
 * 《道高一丈：数字博弈》完整卡牌数据库
 * 
 * 卡牌编号规则: XZYa-bC
 * - X = 来源类代码 (S角色特殊/N正常/L关卡)
 * - Z = 功能类代码 (E资源交换/F基础数值/I即时判定/A延时判定/D数值降低/O其他)
 * - a = 关卡数 (现有卡牌为0，关卡解锁卡牌为对应关卡数)
 * - b = 该卡牌序号
 * - C = 科技树等级 (T1-T5)
 * 
 * 示例: NF0-1T1 = 正常卡牌、基础数值类、现有卡牌第1张、T1等级
 */

